import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, os.path.join(HERE, '..', '..')); sys.path.insert(0, os.path.join(HERE, '..', '..', '..', '..'))
import aeneid_lib as A
# aeneid-038 draft. Drafted from the Latin and grammar only. t is cut from the edition, never typed.
TITLE = 'Imber. Nautes. Anchisae umbra'
TITLE_EN = "The Rain on the Fleet, Nautes' Counsel, and Anchises' Vision — Aeneid V.680–778"
PART = "The Rain on the Fleet, Nautes' Counsel, and Anchises' Vision (V.680–778)"
ABOUT = "The fire that Juno's frenzied women set to the ships will not die: it smoulders in the wet timber and creeps through the hulls, and the heroes' water does nothing. Aeneas tears off his cloak and prays to Jupiter, to spare the fleet or else to strike him down; at once a black storm breaks and drenches the ships, and all but four are saved. Shaken, he turns over whether to stay in Sicily or press on to Italy. Old Nautes, the one man Pallas has taught her arts, advises him: bear what fortune brings, leave the old, the weary and the faint-hearted with Acestes in a city to be called Acesta, and sail on with the bravest. That night his father Anchises comes down from heaven in a dream, sent by Jupiter, and tells him to follow Nautes's counsel, to fight down a hard people in Latium, and first to come to the Underworld by way of Avernus, guided by the Sibyl, where Anchises dwells in Elysium and will show him his race and the walls to come. Aeneas wakes and cannot catch him; he stirs the ashes and worships the Penates and Vesta. Then the city is marked out with a plough, houses are allotted, Acestes gives laws, a temple to Venus is founded on Eryx and a priest and grove for Anchises' tomb. After nine days' feasting the winds turn fair. The parting is full of tears, even from those who had hated the sea; Aeneas commends them to Acestes, sacrifices to Eryx and the Tempests, and, wreathed in olive, pours his offering into the waves from the prow. A following wind rises, and the crews bend to their oars."
U = [
(681, 'posuere;',
 "But not on that account the flames and the fires their strength\nuntamed laid aside;",
 "But the flames and the fires had not for all that laid aside their untamed strength;",
 "A new paragraph, picking up the burning of the ships (the end of the last part). 'Idcirco' is 'on that account', 'for all that'. 'Vires indomitas posuere' is 'laid aside their untamed strength', 'posuere' a perfect in '-ere' for '-erunt' (you'll see this constantly). The Latin Library prints 'flamma… viris', 'flame… with strength', a different case-ending that would change the construction ('indomitas' needs 'vires' as its noun, which Greenough's text supplies)."),
(684, 'prosunt.',
 "under the damp timber it lives, the tow,\nspewing slow smoke, and sluggish on the keels\nis the heat, and through the whole body creeps the plague,\nnor the strength of heroes and the poured waters avail.",
 "Deep in the soaked timber the tow lives on, belching sluggish smoke; the heat clings slowly to the hulls, the plague works down through the whole frame, and neither the efforts of heroes nor the water they pour does any good.",
 "'Udo sub robore' is 'under the damp timber', 'robur' (properly oak) standing for ship's timber, a word you'll meet again. 'Stuppa' is 'tow', the fibre used to caulk a ship's seams, which smoulders inside the wet wood. 'Lentus… vapor' is 'sluggish heat', with 'est' left out, and 'carinas' the keels (the hulls) after 'lentus'. 'Pestis' is 'plague', 'ruin', used of fire as of a sickness spreading through the 'corpus', the ship's body (the metaphor returns at 699, 'a peste'). 'Heroum' is the Greek genitive plural of 'heros'. 'Infusa… flumina' is 'poured-on streams', the water they throw on the fire; 'prosunt' (from 'prosum') is 'avail', with no dative expressed."),
(686, 'palmas:',
 "Then pious Aeneas from his shoulders to tear off his garment,\nand to summon the gods to help, and to stretch out his palms:",
 "Then pious Aeneas tore the cloak from his shoulders, called on the gods to help, and stretched out his palms:",
 "A new paragraph. 'Abscindere', 'vocare' and 'tendere' are historic infinitives, standing for imperfects ('he tore', 'he called', 'he stretched'), as with 'spectare' in the last part; they make the narrative quick. 'Pius' is Aeneas's constant epithet, and here the word to remember, for his prayer rests on it. 'Umeris' is an ablative of separation, 'from his shoulders'; 'auxilio' is a dative of purpose, 'for help'. Palms held up are the ancient posture of prayer. The colon leads to the prayer."),
(690, 'leto.',
 "“Jupiter almighty, if not yet hating to the last one\nthe Trojans, if anything of piety of old the toils\nof men regards, grant the flame to escape the fleet\nnow, Father, and the slender fortunes of the Teucrians snatch from death.",
 "“Almighty Jupiter, if you do not yet hate the Trojans to the last man, if any ancient pity looks on the toils of men, grant that the fleet escape the flame now, Father, and snatch the Teucrians' thin fortunes from death.",
 "The opening mark begins Aeneas's prayer, which runs to 692. 'Si nondum exosus ad unum Troianos' is 'if not yet hating the Trojans to the last one': 'exosus' is a perfect participle of the defective verb 'exodi' with an active sense, 'having come to hate', and 'ad unum' 'down to one', 'to a man'. 'Si quid pietas antiqua labores respicit humanos' is 'if any ancient piety (or pity) regards human toils', 'quid' for 'aliquid'. Whose piety it is is left open: Jupiter's old compassion, or the old devotion of the Trojans. 'Da… evadere' is 'grant to escape', 'do' with a bare infinitive, a poetic construction. 'Teucrum' is the old genitive plural in '-um' (you'll see this constantly). 'Tenues… res' are 'slender fortunes', the little that remains. 'Eripe leto' is 'snatch from death', 'leto' an ablative of separation. The Latin Library prints 'tenuis', the same accusative plural in another spelling."),
(692, 'dextra.”',
 "Or do thou, what is left, with hostile thunderbolt to death,\nif I deserve it, send down, and with thy right hand overwhelm me here.”",
 "Or else, if I deserve it, send down to death whatever is left of us with your angry bolt, and overwhelm us here with your own right hand.”",
 "'Vel' sets the second choice against the first: save the fleet, or finish us. 'Tu' is emphatic, 'you yourself'. 'Quod superest' is 'what remains', a neuter relative for the survivors ('morti' is a dative, 'to death'), with 'infesto fulmine' 'with hostile thunderbolt'. 'Si mereor' is 'if I deserve it', a bare, plain 'if'. 'Demitte' (from 'demitto', 'send down') and 'obrue' ('overwhelm') are singular imperatives, the last in the dative-less form with 'dextra' as an ablative of means. 'Hic' is 'here', on the spot. The closing mark ends the prayer."),
(695, 'campi;',
 "Scarcely these things had he uttered, when with poured-out rains black\na tempest without measure rages, and with thunder tremble\nthe steep places of the lands and the plains;",
 "Hardly had he spoken when a black storm broke in streaming rain, raged beyond all measure, and the high places of the earth and the plains shook with thunder;",
 "'Vix… cum' is the inverted 'cum' pattern, 'scarcely… when', with the pluperfect 'ediderat' for what had barely finished and the present for the sudden answer. 'Effusis imbribus' is an ablative of manner, 'with pouring rains'. 'Atra tempestas' is the 'black storm'; 'sine more' is 'without restraint', 'beyond measure'. 'Tonitru' is an ablative of cause (fourth declension), 'with thunder'. 'Ardua terrarum' is a neuter plural adjective with a partitive genitive, 'the steep (places) of the lands'; the high ground and the 'campi', 'plains', shake together. The prayer is answered at once, a sign of the god's favour."),
(696, 'austris;',
 "rushes from the whole sky\nmurky a rain with water and by thick blackest south winds;",
 "a muddy deluge pours from the whole sky, thick with water and black with crowding southern gales;",
 "'Ruit' is 'comes rushing down', and 'aethere toto' 'from the whole upper air', an ablative of separation. 'Turbidus imber' is a 'murky downpour'; 'aqua' is an ablative of means, 'with water'. 'Densis… austris' is 'with thick south winds', 'austris' a plural for the wind, an ablative of means, with 'nigerrimus' (the superlative of 'niger', 'black') agreeing with 'imber', 'blackest'. The 'Auster' is the south wind, the rain-bringing wind of Italy and Sicily."),
(697, 'puppes;',
 "and are filled from above the sterns;",
 "the sterns fill with water from above;",
 "'Implentur' is passive, 'are filled', with 'puppes' as subject: 'puppis', the stern, stands for the whole ship (part for whole, a figure you saw in the last part), and 'super' is an adverb, 'from above'. The enclitic '-que' joins this short clause to the last."),
(698, 'robora;',
 "half-burnt are soaked\nthe timbers;",
 "the half-burnt timbers are drenched;",
 "'Semiusta' is 'half-burnt' (Greenough's form; the Latin Library prints 'semusta', a shorter spelling of the same word, from 'semi-ustus', from 'uro', 'burn'). 'Madescunt' is an inchoative in '-sco', 'become wet', 'are soaked'. 'Robora', 'timbers', is the word of 681, 'robur', in the plural."),
(699, 'carinae.',
 "until quenched is the heat all, and all,\nfour having been lost, saved from the plague the keels.",
 "until all the heat is quenched, and every hull, though four are lost, is saved from the ruin.",
 "'Donec' is 'until', and 'restinctus… vapor omnis' is 'all the heat quenched', with 'est' left out, as with 'servatae (sunt)'. 'Omnes… carinae' is 'all the keels', 'omnes' split from its noun across the line, with 'quattuor amissis' an ablative absolute, 'four having been lost'. 'A peste' is 'from the plague', the 'pestis' of 683, the fire that spread like a sickness. Four ships are lost, a number to remember."),
(703, 'oras.',
 "But father Aeneas, by the bitter chance shaken,\nnow hither, now thither, in his breast, mighty cares\nwas shifting, turning over — whether in Sicilian fields he should settle,\nforgetful of the fates, or the Italian shores should seize.",
 "But father Aeneas, shaken by the bitter blow, turned vast anxieties this way and that in his breast, weighing whether to settle on Sicilian fields, forgetting the fates, or to make for the shores of Italy.",
 "A new paragraph. 'Pater' is a title of respect, the commander as father of his people. 'Casu concussus acerbo' is 'shaken by the bitter chance', 'casu' an ablative of cause. 'Nunc huc… nunc illuc' is 'now this way, now that', framing 'ingentes… curas', 'mighty cares', as objects of 'mutabat versans', 'was shifting, turning over', the verb and its participle saying the same thing twice, for restlessness. 'Siculisne… Italasne' is the double question 'whether… or' with '-ne… -ne', and 'resideret' and 'capesseret' are imperfect subjunctives in an indirect question. 'Capesseret' is an intensive form of 'capio', 'take eagerly', 'make for'. 'Oblitus fatorum' is a perfect participle with the genitive: to stay would be to forget the fates (the promise of Italy). The Latin Library prints 'ingentis', the same accusative plural spelled with '-is'."),
(707, 'ordo;',
 "Then the elder Nautes, whom alone Tritonian Pallas\nhad taught and rendered distinguished with much art,\nthese replies was giving, whether what might portend the wrath\ngreat of the gods, or what the order of the fates might demand;",
 "Then aged Nautes, the one man whom Tritonian Pallas had taught and made renowned for her many arts, began to give such answers as either the great wrath of the gods foretold or the order of the fates required;",
 "'Nautes' is an old Trojan counsellor, said to be the ancestor of the Roman family of the Nautii, who kept a cult of Pallas. 'Unum… quem' is 'him alone whom', 'unum' a predicative accusative: Pallas had taught him alone. 'Tritonia Pallas' is Athena, 'Tritonia' one of her epithets (from Lake Triton, where she was said to have been born). 'Docuit' and 'reddidit' are perfects, and 'multa… arte' an ablative of means. 'Responsa dabat' is 'was giving answers', the imperfect for his habit of advising. 'Vel quae portenderet… vel quae… posceret' is a double indirect question, 'either what… portended, or what… demanded', with imperfect subjunctives. 'Deum' is the old genitive plural in '-um' (you'll see this constantly), 'of the gods'."),
(708, 'infit:',
 "and he, with these words Aeneas consoling, begins:",
 "and he, comforting Aeneas, began with these words:",
 "'Isque' is 'et is', 'and he'. 'Solatus' is a perfect participle of the deponent 'solor', 'having consoled', 'consoling', with an active sense. 'Infit' is a defective verb, found only in a few forms, 'begins (to speak)', an archaism; it governs the speech after the colon."),
(709, 'sequamur;',
 "“Goddess-born, whither the fates draw and draw back, let us follow;",
 "“Son of a goddess, let us follow wherever the fates lead on or draw back;",
 "A new paragraph, and the beginning of Nautes's speech, which runs to 718. 'Nate dea' is 'son born of a goddess', 'nate' a vocative and 'dea' an ablative of origin, as 'dea nate' of Aeneas's mother Venus. 'Quo fata trahunt retrahuntque' is 'where the fates draw and draw back', 'retrahunt' the compound that adds the opposite pull, 'to and fro' for advance or setback (the double '-que' recurs). 'Sequamur' is a hortatory subjunctive, 'let us follow'."),
(710, 'est.',
 "whatever it shall be, to be overcome all fortune by bearing is.",
 "whatever comes, every fortune is to be overcome by bearing it.",
 "'Quidquid erit' is 'whatever will be', an unfinished clause in the future with 'quidquid' for 'quicquid'. 'Superanda… est' is the passive periphrastic, 'is to be overcome', 'must be overcome', with 'omnis… fortuna' as subject and 'ferendo' an ablative of the gerund, 'by bearing', 'by endurance': the gist of Stoic advice, in four words."),
(711, 'Acestes:',
 "There is to you Dardanian of divine stock Acestes:",
 "You have Acestes, a Trojan by descent and of divine stock:",
 "'Est tibi' is a dative of possession, 'you have' (you'll see this constantly), the thing possessed 'Acestes' set at the end. 'Dardanius' is 'of Dardanus's line', 'Trojan': Acestes's mother was a Trojan woman (told at the start of Book V). 'Divinae stirpis' is a genitive of quality, 'of divine stock', his father being a river-god. The colon leads on to what Aeneas is to do with him."),
(712, 'volentem;',
 "him take as ally into your counsels and join, willing;",
 "take him into your counsels as an ally, and join him to you, for he is willing;",
 "'Hunc cape… socium' is 'take him as ally', 'socium' a predicative accusative, and 'consiliis' a dative, 'for your counsels', 'into your plans'. 'Coniunge' is the imperative of 'coniungo', 'join (to you)'. 'Volentem' is a present participle agreeing with 'hunc', 'willing', 'since he is willing'."),
(714, 'est;',
 "to him hand over those who survive, the ships being lost, and those whom\nit has thoroughly wearied of the great undertaking and of your affairs;",
 "To him hand over those who are left, now that the ships are lost, and those who have grown weary of the great enterprise and of your cause;",
 "'Huic trade' is 'hand over to him', 'huic' a dative. 'Amissis… navibus' is an ablative absolute, 'the ships having been lost'; 'superant… qui' is 'those who survive' ('supero' in its sense 'remain over'). 'Quos pertaesum… est' is the impersonal 'pertaedet', 'it wearies thoroughly', with the accusative of the person ('quos') and the genitives of the thing: 'magni incepti', 'of the great undertaking' ('inceptum', a perfect participle used as a noun), and 'rerum tuarum', 'of your affairs', 'of your cause'. These are the ones too weary to go on."),
(717, 'fessi:',
 "and the long-lived old men and the mothers weary with the sea,\nand whatever with you is weak and fearful of danger,\nchoose out, and in these lands allow them to have walls, the weary:",
 "Pick out the aged men and the mothers worn out by the sea, and all in your company who are weak and afraid of danger, and let the weary have walls in these lands:",
 "'Longaevos… senes' are 'long-lived old men', 'fessas aequore matres' 'mothers weary from the sea' ('aequore' an ablative of cause). 'Quidquid tecum invalidum metuensque pericli est' is 'whatever is weak with you and fearful of danger': 'quidquid' is neuter, so it covers anyone and anything, 'metuens' takes the genitive 'pericli', a syncopated form of 'periculi', Virgil's usual shortening. 'Delige' is the imperative of 'deligo', 'choose out', and governs all three. 'Sine' is the imperative of 'sino', 'allow', followed by 'habeant', a subjunctive without 'ut' ('allow that they have'); 'his… terris' is 'in these lands', and 'fessi' is the subject, the weary, left at the end."),
(718, 'Acestam.”',
 "a city they will call, the name permitted, Acesta.”",
 "and they will call the city Acesta, by the name you permit.”",
 "'Urbem appellabunt' is 'they will name the city', with 'Acestam' in agreement as the name, the Greek-style accusative of the thing named. 'Permisso nomine' is an ablative absolute, 'the name being permitted', that is, with Aeneas's leave and with Acestes honoured by the name; this is the city later known in Sicily as Segesta. The closing mark ends Nautes's speech."),
(720, 'omnes.',
 "By such words kindled of an elder friend,\nthen indeed into cares in his mind he is torn apart, all.",
 "Stirred by this speech from his aged friend, he was now pulled apart in mind among all his cares.",
 "A new paragraph. 'Talibus incensus dictis' is 'kindled by such words', 'incensus' the perfect participle passive of 'incendo', and 'senioris amici' a genitive with 'dictis', 'of his elder friend'. 'Tum vero' is 'then indeed', marking the effect. 'Diducitur' is the present passive of 'diduco', 'is drawn apart': he was pulled this way and that by his cares even more than before. 'Animo' is an ablative of respect, 'in his mind'; 'in curas… omnes' is 'into all his cares'. The Latin Library prints 'omnis', the same accusative plural in another spelling."),
(721, 'tenebat:',
 "And night, black, the sky on her two-horse chariot mounting, held:",
 "And dark Night, borne up on her chariot, held the heavens:",
 "'Nox atra' is 'black night', and 'bigis' an ablative of means, 'on a two-horse chariot', the common picture of Night driving across the sky. 'Subvecta' is the perfect participle of the deponent 'subvehor', 'carried up', here 'mounted'. 'Polum… tenebat' is 'held the vault of heaven', 'polus' the sky. The colon introduces the vision."),
(723, 'voces:',
 "the appearance then from heaven slipped down of his father\nAnchises suddenly such to pour forth words:",
 "then the form of his father Anchises seemed to glide down from heaven and suddenly pour out such words:",
 "'Visa… facies… effundere' is 'the form seemed to pour out', 'visa' (with 'est' left out) a perfect passive of 'video' in the sense 'seemed', with the infinitive. 'Facies' is the appearance, 'shape', here a dream-image; 'delapsa' is the perfect participle of 'delabor', 'slipped down', and 'caelo' an ablative of separation, 'from the sky'. 'Parentis Anchisae' is 'of his parent Anchises', the genitive 'parentis' set before the name. 'Tales… voces' is 'such words'; the Latin Library prints 'talis', the same accusative plural in another spelling. The colon leads to Anchises's speech."),
(727, 'est.',
 "“Son, to me than life once, while life remained,\ndearer, son, harried by Ilian fates,\nby Jove's command I come here, who from your fleet the fire\ndrove off, and from heaven at last has pitied from on high.",
 "“My son, once dearer to me than life itself, while life remained, my son, tried by the fates of Ilium, I come at Jove's command, who has driven the fire from your ships and has at last taken pity from high heaven.",
 "The opening mark begins Anchises's speech, which runs to 739. 'Mihi vita quondam… care magis' is 'dearer to me than life once', with 'vita' an ablative of comparison. 'Dum vita manebat' is 'while life remained', 'dum' with the imperfect indicative. 'Nate' is repeated, a tender double address. 'Exercite' is a vocative, the perfect participle of 'exerceo', 'harassed', 'worn down', 'Iliacis fatis' 'by the fates of Ilium'. 'Imperio Iovis' is an ablative of cause, 'by Jove's order'; 'qui' is the relative, 'he who', with 'classibus' a dative of separation, 'from the fleets'. 'Depulit' is 'drove off'. 'Miseratus… est' is the perfect of the deponent 'miseror', 'has pitied', split by tmesis (a word cut in two) around 'ab alto caelo', here 'caelo… ab alto', 'from high heaven'. The sense is that Jupiter heard the prayer of 687–692."),
(729, 'senior;',
 "To counsels give heed, which now the best Nautes\ngives, the elder;",
 "Heed the counsel that old Nautes now gives, the best that could be given;",
 "'Consiliis pare' is 'obey the counsels', 'pare' the imperative of 'pareo', which takes the dative. 'Quae nunc pulcherrima… dat' is 'which, the finest, he now gives', 'pulcherrima' a superlative agreeing with 'quae', 'most excellent'. 'Senior' is 'the elder', 'the old man', in apposition to 'Nautes'. The ghost thereby endorses what Nautes said."),
(730, 'Italiam;',
 "chosen young men, the bravest hearts,\ncarry to Italy;",
 "carry to Italy the chosen young men, the bravest hearts;",
 "'Lectos iuvenes' are 'chosen young men', objects of 'defer', 'carry down', 'bring' (the imperative of 'defero'). 'Fortissima corda' is an apposition in the neuter plural to masculine nouns ('hearts' for brave spirits, a construction by sense), 'the bravest hearts'."),
(731, 'est.',
 "a race hard and rough in way of life\nis to be conquered by you in Latium.",
 "In Latium you must fight down a race hard and rough in its ways.",
 "'Gens dura atque aspera cultu' is 'a race hard and rough in its manner of life', 'cultu' an ablative of respect. 'Debellanda tibi… est' is a passive periphrastic with a dative of the agent, 'is to be fought to the finish by you', 'debello' with 'de-' as an intensive, 'fight down'. 'Latio' is an ablative of place, 'in Latium'; the hard people are the Latins and Rutulians of the later books."),
(733, 'meos.',
 "Of Dis, however, before that\nthe infernal approach houses, and through Avernian heights\nseek meetings, son, mine.",
 "But before that, go to the infernal home of Dis, and through the deep places of Avernus seek out a meeting with me, my son.",
 "'Ditis' is the genitive of 'Dis', the king of the dead, Pluto. 'Ante' is an adverb, 'first', 'before that', with 'tamen', 'nevertheless': the founding in Latium has to wait for a journey below. 'Accede' is the imperative of 'accedo', 'approach', with the accusative 'infernas… domos', 'the houses below'. 'Averna per alta' is 'through the deep places of Avernus', 'Averna' neuter plural, 'per' placed after its adjective: the lake Avernus near Cumae was one entrance to the Underworld. 'Congressus' is a fourth-declension accusative plural, 'meetings', and 'pete… meos' is 'seek my meetings', that is, 'come and meet me'."),
(735, 'colo.',
 "Not me impious\nTartarus holds, sad shades, but pleasant, of the pious\nassemblies and Elysium I inhabit.",
 "For no wicked Tartarus holds me, among sad shades, but I dwell in the pleasant gatherings of the pious and in Elysium.",
 "'Namque' is 'for', set after its first words. 'Impia Tartara' is 'impious Tartarus', neuter plural, 'impia' a transferred epithet: Tartarus is where the impious are held. 'Tristes umbrae' is 'the sad shades', a phrase in apposition to what 'Tartara' holds. 'Amoena piorum concilia' is 'the pleasant assemblies of the pious', 'concilia' (with 'Elysium') the objects of 'colo', 'I dwell in', 'I haunt'. Elysium is the Blessed's abode. 'Colo' also carries the sense 'I tend': he lives there, and he promises the sights of Book VI."),
(736, 'ducet:',
 "Hither the chaste Sibyl\nof black cattle with much blood will lead you:",
 "Hither the chaste Sibyl will lead you, once the blood of many black cattle has flowed:",
 "'Huc' is 'hither', to Elysium. 'Casta Sibylla' is 'the chaste Sibyl', the virgin prophetess of Cumae, priestess of Apollo, who will be Aeneas's guide in Book VI. 'Nigrarum multo pecudum sanguine' is 'with the blood of many black beasts', an ablative of means: black victims were offered to the powers of the Underworld. The colon leads on to what he will learn there."),
(737, 'disces.',
 "then your whole race, and what walls may be given, you will learn.",
 "There you will learn of all your line, and what walls are to be given you.",
 "'Genus omne tuum' is 'your whole race', your descendants. 'Quae dentur moenia' is an indirect question, 'what walls are to be given', 'dentur' a present subjunctive. 'Disces' is the future of 'disco'. This promises the parade of Rome's future heroes in VI."),
(738, 'vale:',
 "And now farewell:",
 "And now farewell:",
 "'Iamque vale' is 'and now farewell', 'vale' the imperative of 'valeo', the ordinary Latin goodbye; the colon leads to the reason, that the night is passing and he must go. The ghost's visit is short."),
(739, 'anhelis.”',
 "turns the middle courses Night, dewy,\nand me the cruel Orient with panting horses has breathed upon.”",
 "dewy Night is turning through the middle of her course, and the cruel East has breathed on me with the panting horses of the dawn.”",
 "'Torquet medios… cursus' is 'turns her middle course', 'medios' agreeing with 'cursus': Night is at her half-way point and driving down. 'Humida' is 'moist', 'dewy' (the Latin Library prints it without the 'h', 'umida'). 'Me… adflavit' is 'has breathed upon me', 'adflavit' Greenough's spelling of 'afflavit', 'equis… anhelis' an ablative of means, 'with panting horses': the dawn's horses breathe on him, a sign that the shades must go back before daybreak. 'Saevus Oriens' is 'the cruel East'. The closing mark ends Anchises's speech."),
(740, 'auras.',
 "He had spoken, and thin fled, like smoke, into the breezes.",
 "He had spoken, and, thin as smoke, he fled into the air.",
 "'Dixerat' is a pluperfect, the usual Virgilian way of ending a speech, 'he had spoken'. 'Tenuis' is a masculine nominative singular adjective, 'thin', 'airy', agreeing with the ghost (with 'fugit', 'fled'); the same spelling is used for the accusative plural at 690. 'Ceu fumus' is 'like smoke', 'ceu' a poetic 'as'. 'In auras' is 'into the breezes', 'into thin air'. The dream-father vanishes as Creusa's ghost did in Book II."),
(742, 'arcet?”',
 "Aeneas: “Where then do you rush, where do you hurry off?” he says,\n“Whom do you flee, or who from our embraces bars you?”",
 "Aeneas cried: “Where do you rush off to now, where do you tear yourself away?” he said; “whom do you flee, or who keeps you from our embrace?”",
 "The print has 'proripis? ”inquit,', the closing mark of Aeneas's first cry set after the space and joined to 'inquit', a misprint for 'proripis?” inquit,'; t keeps the print, and l and i close the cry after 'proripis?'. The second cry has its own opening mark at 742. 'Aeneas' is the subject of an understood 'inquit', with 'inquit' placed after the speech. 'Quo deinde ruis, quo proripis' is 'where then are you rushing, where tearing yourself away?', 'proripis' a reflexive use of 'proripio' with 'te' left out, and 'quo' repeated. 'Quem fugis' is 'whom do you flee?', 'quis… arcet' 'who keeps you off', 'nostris complexibus' an ablative of separation, 'from our embraces'. Odysseus's three tries to hold his mother's shade in Odyssey 11 stand behind this."),
(745, 'acerra.',
 "These things speaking, the ashes and the sleeping fires he stirs up,\nand the Pergamean Lar and of hoary Vesta the inner shrine\nwith pious meal and a full censer, suppliant, he worships.",
 "Saying this, he stirs the ashes and the slumbering fires, and, as a suppliant, worships the Lar of Pergamum and the inner shrine of hoary Vesta with sacred meal and a full censer of incense.",
 "'Haec memorans' is 'saying these things', 'memorans' from 'memoro', 'speak of'. 'Cinerem et sopitos… ignes' are 'the ash and the sleeping fires', the embers of a hearth that he rouses to make an offering (the Latin Library prints 'ignis', the same accusative plural in another spelling). 'Pergameum Larem' is 'the Lar of Pergamum', the household god of Troy (Pergamum is Troy's citadel); 'canae penetralia Vestae' is 'the inner shrine of hoary Vesta', 'penetralia' a neuter plural for the innermost part of a temple or house, and Vesta the goddess of the hearth, whose fire Aeneas brought from Troy. 'Farre pio et plena… acerra' is 'with pious meal and a full incense-box', two ablatives of means: 'far' is the coarse spelt-meal for offerings. 'Supplex' is 'as a suppliant', predicative, and 'veneratur' a deponent, 'worships'."),
(748, 'constet.',
 "Immediately his comrades and first Acestes he summons,\nand of Jove the command and of his dear father the precepts\nhe teaches fully, and what now in his mind the decision stands.",
 "At once he summons his comrades, and Acestes first of all, and tells them fully of the command of Jupiter, the precepts of his dear father, and what resolve is now fixed in his mind.",
 "A new paragraph. 'Extemplo' is 'at once'. 'Arcessit' is 'summons', Greenough's spelling (the Latin Library prints 'accersit', the same word). 'Primum… Acesten' is 'Acestes first', 'Acesten' a Greek accusative. 'Edocet' is 'teaches thoroughly', 'tells in full', and takes three objects: 'imperium', 'praecepta' and an indirect question, 'quae… sententia constet', 'what decision stands firm', 'constet' a present subjunctive. 'Animo' is a dative or ablative with 'constet', 'in his mind'. Note that Aeneas tells them of the command of Jupiter as well as the precepts of Anchises, the very words of 726–727."),
(749, 'Acestes.',
 "No delay to the counsels, nor the orders refuses Acestes.",
 "There is no delay in carrying out the plan, and Acestes does not refuse the orders.",
 "'Haud mora' is 'no delay', with 'est' left out, and 'consiliis' a dative, 'to the counsels', 'as to the plans'. 'Iussa' is a neuter plural, 'the orders', a perfect participle used as a noun; 'recusat' is 'refuses'. Acestes agrees at once, as the allies will."),
(751, 'egentes.',
 "They transcribe to the city the mothers, and the people willing\nthey set down, spirits of nothing great in praise needing.",
 "They enrol the mothers in the new city, and settle the willing people there, souls that have no need of great renown.",
 "'Transcribunt' is 'enrol', 'transfer', from 'transcribo', 'write over', used of entering names on the roll of a new city, with 'urbi' a dative. 'Populum volentem deponunt' is 'they set down the willing people', 'deponunt' 'leave behind'. 'Animos… egentes' is an accusative apposition to the people, 'spirits needing nothing of great praise', 'egeo' taking the genitive 'laudis', and 'nil' an accusative of the extent: these are the weary, who want no heroism. The Latin Library prints 'egentis', the same accusative plural in another spelling."),
(754, 'virtus.',
 "They themselves the benches renew, and by flames gnawed they replace\ntimbers in the ships, and fit oars and ropes,\nfew in number, but in war lively valour.",
 "They themselves renew the benches and replace for the ships the timbers the flames had gnawed, and fit oars and ropes, few in number, but their courage alive for war.",
 "'Ipsi' is 'they themselves', the Trojan crews who go on. 'Transtra novant' is 'renew the benches', the rowers' cross-seats. 'Flammisque ambesa… robora' is 'timbers gnawed round by flames', 'ambesa' the perfect participle passive of 'ambedo', 'eat around', 'flammis' an ablative of means; 'reponunt… navigiis' is 'put back for the vessels', 'navigiis' a dative (the diminutive 'navigium', a ship). 'Aptant' is 'fit out'. 'Rudentes' are 'ropes', rigging (the Latin Library prints 'rudentisque', the same accusative plural). 'Exigui numero' is 'small in number', 'numero' an ablative of respect, nominative plural with 'ipsi'; 'vivida virtus' is 'lively valour', 'est' left out: the picked few have the strength of many."),
(756, 'domos;',
 "Meanwhile Aeneas the city marks out with the plough\nand allots the homes;",
 "Meanwhile Aeneas marks out the city with a plough and allots the homesteads;",
 "'Urbem designat aratro' is 'marks out the city with the plough', 'aratro' an ablative of means: the Roman rite of founding a city, by ploughing a furrow around the walls' line. 'Sortitur… domos' is 'allots by lot the dwellings', 'sortior' a deponent, 'domos' an accusative plural."),
(757, 'iubet.',
 "this Ilium and these places Troy\nto be he bids.",
 "Here, he decrees, shall be Ilium, and this land Troy.",
 "'Hoc Ilium et haec loca Troiam esse iubet' is an accusative and infinitive after 'iubet', 'he orders this (place) to be Ilium and these places Troy', 'Ilium' (neuter) the city and 'Troiam' the country round it, 'loca' the plural 'places'. As at III.349–351, new names for old."),
(758, 'vocatis.',
 "Rejoices in the kingdom the Trojan Acestes,\nand proclaims a forum and gives laws to the senators summoned.",
 "Trojan Acestes rejoices in his new realm, appoints a forum, and gives laws to the fathers he has summoned.",
 "'Gaudet regno' is 'rejoices in the kingdom', 'regno' an ablative of cause, as 'gaudeo' often takes. 'Troianus Acestes' is 'Trojan Acestes', as 'Dardanius' at 711. 'Indicit forum' is 'proclaims a forum', 'appoints a market-place and court', and 'patribus… vocatis' is 'to the fathers called together', 'patres' the senators, 'vocatis' a perfect participle passive. The Roman words ('forum', 'patres', 'iura') make the new town a small Rome."),
(761, 'Anchiseo.',
 "Then near to the stars, on Eryx's summit, a seat\nis founded for Idalian Venus, and for the tomb a priest\nand a grove far and wide sacred is added of Anchises.",
 "Then, close to the stars, on the summit of Eryx a shrine is founded for Idalian Venus, and a priest and a grove, sacred for a great distance round, are added to Anchises' tomb.",
 "'Tum' is 'then'. 'Vicina astris' is 'neighbouring the stars', 'vicina' with a dative, agreeing with 'sedes', and 'Erycino in vertice' 'on the Erycine peak', 'Erycinus' the adjective of Mount Eryx, in western Sicily. 'Sedes fundatur' is 'a seat (a temple) is founded', for 'Veneri Idaliae', 'Idalian Venus', named from Idalium in Cyprus, where she was worshipped. 'Tumulo… Anchiseo' is a dative, 'to the Anchisean tomb', the adjective standing for the genitive. 'Sacerdos ac lucus' make a double subject, with the singular verb 'additur' agreeing with the nearer ('lucus late sacer'). The Latin Library prints 'additus', a participle, so that the clause would run on with 'est' understood; the sense is the same."),
(763, 'honos:',
 "And now days having feasted nine the people all, and on the altars\nhonour has been done:",
 "Now the whole people had feasted for nine days, and honour had been paid at the altars:",
 "A new paragraph. 'Iamque' is 'and now'. 'Dies epulata novem gens omnis' is 'the whole people having feasted nine days', 'epulata' the perfect participle of the deponent 'epulor' with an active sense, 'dies novem' an accusative of duration: the nine-day feast ('novendiale') was the Roman funeral custom. 'Aris factus honos' is 'honour done at the altars', 'est' left out, 'honos' the sacrifice."),
(764, 'altum.',
 "gentle have levelled the seas the winds,\nand thick and breathing again calls the South wind into the deep.",
 "the gentle winds have smoothed the water, and the South wind, blowing steadily once more, calls them out to the open sea.",
 "'Placidi straverunt aequora venti' is 'the calm winds have levelled the seas', 'straverunt' a perfect in '-erunt' (contracted from 'stravi'). 'Creber' is 'thick', 'frequent', a steady wind, with 'adspirans' (the Latin Library prints it 'aspirans'), 'blowing on' (them). 'Auster' is the south wind, and 'in altum' 'into the deep sea', 'altum' a neuter noun for the open sea. 'Rursus' is 'again'."),
(765, 'fletus;',
 "There arises along the curved shores a huge wailing;",
 "A great wailing rises all along the curving shore;",
 "'Exoritur' is 'arises', 'procurva… per litora' 'along the curving shores', 'procurvus' meaning 'bending forward' (a bay). 'Ingens fletus' is 'a great weeping', a fourth-declension noun."),
(766, 'morantur.',
 "embraced among themselves, night and day they linger.",
 "Locked in each other's arms they linger night and day.",
 "'Complexi' is the perfect participle of the deponent 'complector', 'having embraced', with an active sense. 'Inter se' is 'one another'. 'Noctemque diemque' is a double '-que', 'both night and day', an accusative of duration, and 'morantur' 'they linger', 'delay'."),
(769, 'laborem.',
 "The very mothers now, themselves, to whom bitter once\nseemed the face of the sea and the name not to be endured,\nwish to go, and all the toil of flight to bear through.",
 "Even the mothers now, and the very men to whom the face of the sea once seemed harsh and its name unbearable, are ready to go and to endure all the toil of flight.",
 "'Ipsae… matres, ipsi' is 'the mothers themselves, the men themselves', the emphasis on the very ones who had hated the sea (the women of 615–617). 'Quibus… visa' is 'to whom seemed', 'visa (est)' with 'aspera' predicative, 'harsh', 'maris facies' 'the face of the sea'. 'Non tolerabile nomen' is 'the unbearable name': the Latin Library prints 'numen', 'divinity', for 'nomen', 'name', a difference of sense, though both would fit the sea as a force to be feared. 'Ire volunt… perferre' is 'wish to go and to bear through', 'perferre omnem laborem' 'endure all the toil to the end', 'fugae' a genitive, 'of the flight' from Troy."),
(771, 'Acestae.',
 "Whom good Aeneas with words kind consoles,\nand to his kinsman, weeping, commends Acestes.",
 "Good Aeneas comforts them with kind words, and with tears commends them to his kinsman Acestes.",
 "'Quos' is a connecting relative, 'and them' (you'll see this constantly). 'Bonus Aeneas' is 'good Aeneas', 'dictis… amicis' 'with kindly words', an ablative of means. 'Solatur' is the present of the deponent 'solor'. 'Consanguineo… Acestae' is a dative, 'to his kinsman Acestes', 'Acestae' the dative of the Greek-type name 'Acestes' (accusative 'Acesten' at 746); the kinship is that of Trojan blood. 'Lacrimans' is 'weeping', 'commendat' is 'entrusts'."),
(773, 'funem.',
 "Three to Eryx calves and to the Tempests a ewe lamb\nto slaughter then he orders, and to be loosed in order the cable.",
 "Then he orders three calves to be slain for Eryx and a ewe-lamb for the Tempests, and the cable to be cast off in order.",
 "'Tris' is Greenough's accusative plural in '-is', 'three' (you'll see this constantly). 'Eryci' is a dative, 'for Eryx', the hero and deity of the mountain, 'Tempestatibus' a dative, 'for the Tempests', the storm-powers worshipped at Rome as Tempestates. 'Caedere' and 'solvi' are infinitives after 'iubet', the second passive, 'to be loosed', with 'funem' as its subject, 'ex ordine' 'in due order', each ship in its turn. Sacrifice to storm-spirits aims to keep them calm."),
(776, 'fundit.',
 "Himself, his head with leaves bound of trimmed olive,\nstanding far off on the prow holds the bowl, and the entrails into the salt\nwaves casts and wine flowing pours.",
 "Himself, his head wreathed with leaves of trimmed olive, standing apart on the prow he holds the bowl, flings the entrails into the salt waves, and pours out the flowing wine.",
 "'Ipse' is Aeneas himself. 'Caput… evinctus' is 'bound as to the head', 'caput' an accusative of respect, 'evinctus' the perfect participle passive of 'evincio'; 'tonsae… olivae' is 'of a trimmed olive', the olive branch used as a priest's wreath. 'Procul in prora' is 'apart on the prow', 'pateram tenet' 'holds the libation bowl'. 'Exta' are the entrails of the victims, thrown into the sea as the offering, 'salsos… in fluctus' 'into the salt waves' (the Latin Library prints 'proicit' for Greenough's 'proiicit', the same word). 'Vina liquentia' is 'liquid wine', the libation, and 'fundit' 'pours out'."),
(777, 'euntes.',
 "Follows, rising from the stern, a wind them going.",
 "A wind rises from astern and follows them as they go.",
 "The Latin Library does not print this line at all; Greenough prints it, unbracketed. The paragraph reads smoothly either way, but the wind does need to come from somewhere to send the ships off. 'Prosequitur' is 'follows', 'sees off', with 'euntes' an accusative present participle, 'them going', and 'a puppi' 'from the stern', 'a following wind'. 'Surgens' is 'rising', agreeing with 'ventus'."),
(778, 'verrunt.',
 "Eagerly the comrades strike the sea and the waters sweep.",
 "The crews vie with one another as they beat the sea and sweep the waters.",
 "'Certatim' is 'in rivalry', each crew eager to be first. 'Feriunt mare et aequora verrunt' is 'strike the sea and sweep the levels', 'verro' ('sweep') the verb for rowing, as 'feriunt' ('strike') for the oars' blow: two ways of saying that they row with all their strength. The scene closes the Sicilian stay and leads to the open sea and Palinurus."),
]
P = A.part('aeneid-038'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units')
